-- ============================================================
-- ShiftSouq: demo catalogue seed
-- GENERATED by scripts/catalog/build-seed.mjs from catalog/catalog.json.
-- Do not edit by hand: change catalog/catalog.json and run
--   npm run catalog:seed
-- Safe to run more than once. Products, variants and images are matched by
-- slug / SKU; no user accounts, reviews or orders are created.
-- Photos: Unsplash (free licence); credits are in catalog/catalog.json.
-- ============================================================

BEGIN;

-- ── Previous demo catalogue ───────────────────────────────────
-- Order lines keep their own name, price and image, so removing these is safe for old orders.
DELETE FROM products WHERE slug IN ('classic-navy-polo', 'essential-white-polo', 'linen-summer-shirt', 'chino-trousers-beige', 'kids-denim-jacket', 'kids-graphic-tee', 'urban-runner-x', 'classic-canvas-low', 'leather-wallet-black', 'aviator-sunglasses', 'formal-oxford-shoes', 'everyday-zip-up-hoodie', 'kids-cotton-shorts', 'kids-slip-on-sneakers', 'retro-high-tops', 'slip-resistant-trainers', 'summer-resort-shirt', 'winter-puffer-coat', 'classic-leather-belt', 'essential-cargo-pants');
DELETE FROM categories c WHERE c.slug = 'polo'
  AND NOT EXISTS (SELECT 1 FROM products p WHERE p.category_id = c.id)
  AND NOT EXISTS (SELECT 1 FROM categories k WHERE k.parent_id = c.id);
DELETE FROM categories c WHERE c.slug = 'kids'
  AND NOT EXISTS (SELECT 1 FROM products p WHERE p.category_id = c.id)
  AND NOT EXISTS (SELECT 1 FROM categories k WHERE k.parent_id = c.id);
DELETE FROM categories c WHERE c.slug = 'collections'
  AND NOT EXISTS (SELECT 1 FROM products p WHERE p.category_id = c.id)
  AND NOT EXISTS (SELECT 1 FROM categories k WHERE k.parent_id = c.id);
DELETE FROM categories c WHERE c.slug = 'men'
  AND NOT EXISTS (SELECT 1 FROM products p WHERE p.category_id = c.id)
  AND NOT EXISTS (SELECT 1 FROM categories k WHERE k.parent_id = c.id);

