INSERT INTO categories (id, parent_id, slug, name_en, name_ar, description_en, description_ar, image_url, sort_order, is_active, is_featured) VALUES
  ('e5b89257-c1f8-58b3-badf-d0717fbcecdc', NULL, 'clothing', 'Clothing', 'ملابس', 'Shirts, polos, knitwear and trousers in natural fabrics, cut for everyday wear.', 'قمصان وبولو وكنزات وبناطيل من خامات طبيعية، بقصّات للاستخدام اليومي.', 'https://images.unsplash.com/photo-1633655442432-620aa55d7ac1?w=1200&h=1500&q=80&auto=format&fit=crop', 1, true, false),
  ('bcc4ed07-6713-5e21-af41-90e1a139fd98', NULL, 'shoes', 'Shoes', 'أحذية', 'Sneakers, loafers and dress shoes in leather, suede and canvas.', 'أحذية رياضية ولوفر وأحذية رسمية من الجلد والسويد والقماش.', 'https://images.unsplash.com/photo-1657034321685-1fba1b2751f3?w=1200&h=1500&q=80&auto=format&fit=crop', 2, true, false),
  ('a5fb33e2-09a6-537f-941e-989a47f4bb42', NULL, 'accessories', 'Accessories', 'إكسسوارات', 'Bags, watches, leather goods and sunglasses to finish the look.', 'حقائب وساعات ومنتجات جلدية ونظارات شمسية تكمل إطلالتك.', 'https://images.unsplash.com/photo-1676276550322-7623a2545b24?w=1200&h=1500&q=80&auto=format&fit=crop', 3, true, false)
