  ('50f82cbb-3b41-5093-a6a8-d5bc7c9dd7f2', (SELECT id FROM categories WHERE slug = 'clothing'), 'knitwear', 'Knitwear', 'كنزات', 'Merino, cable and ribbed knits for cooler evenings.', 'كنزات من الميرينو وبنقشة الضفائر وبنسيج مضلّع للأمسيات الباردة.', 'https://images.unsplash.com/photo-1646270968802-6bad28659329?w=1200&h=1500&q=80&auto=format&fit=crop', 5, true, true),
  ('1dea3c38-1d6d-5b05-9c6f-e2ae2f721267', (SELECT id FROM categories WHERE slug = 'clothing'), 'jackets', 'Jackets', 'سترات', 'Denim, leather and field jackets to layer through the seasons.', 'سترات من الدنيم والجلد وسترات خارجية خفيفة لكل المواسم.', 'https://images.unsplash.com/photo-1617114919297-3c8ddb01f599?w=1200&h=1500&q=80&auto=format&fit=crop', 6, true, false),
  ('584df780-3b4e-5e63-93c7-7f02111e71b5', (SELECT id FROM categories WHERE slug = 'shoes'), 'sneakers', 'Sneakers', 'أحذية رياضية', 'Clean, logo-free sneakers in leather, suede and canvas.', 'أحذية رياضية بسيطة بلا شعارات من الجلد والسويد والقماش.', 'https://images.unsplash.com/photo-1603808033176-9d134e6f2c74?w=1200&h=1500&q=80&auto=format&fit=crop', 1, true, true),
  ('0090ffeb-d091-59f1-84e5-e7bfd5904895', (SELECT id FROM categories WHERE slug = 'shoes'), 'loafers-formal', 'Loafers & Formal', 'لوفر وأحذية رسمية', 'Loafers, oxfords, derbies and Chelsea boots for work and occasions.', 'أحذية لوفر وأكسفورد وديربي وتشيلسي للعمل والمناسبات.', 'https://images.unsplash.com/photo-1556004583-d2aaffbba592?w=1200&h=1500&q=80&auto=format&fit=crop', 2, true, true),
  ('43823bb9-ecbe-5ff9-ad02-464895213e32', (SELECT id FROM categories WHERE slug = 'accessories'), 'bags', 'Bags', 'حقائب', 'Weekenders, briefcases and totes in canvas and leather.', 'حقائب سفر وأوراق وحقائب يد من القماش والجلد.', 'https://images.unsplash.com/photo-1654773215728-4387196bc2a8?w=1200&h=1500&q=80&auto=format&fit=crop', 1, true, false),
  ('e2fa7fc1-b5c5-519b-9e05-da528335e004', (SELECT id FROM categories WHERE slug = 'accessories'), 'watches', 'Watches', 'ساعات', 'Minimal watches with clean dials on leather and steel.', 'ساعات بسيطة بموانئ واضحة على أساور من الجلد والفولاذ.', 'https://images.unsplash.com/photo-1603572143491-88cf91cd9330?w=1200&h=1500&q=80&auto=format&fit=crop', 2, true, true),
  ('7164a29d-e2d2-5680-b4e4-96ae640236f9', (SELECT id FROM categories WHERE slug = 'accessories'), 'belts-wallets', 'Belts & Wallets', 'أحزمة ومحافظ', 'Belts, wallets and card holders in full-grain leather.', 'أحزمة ومحافظ وحافظات بطاقات من الجلد الطبيعي.', 'https://images.unsplash.com/photo-1711443982852-b3df5c563448?w=1200&h=1500&q=80&auto=format&fit=crop', 3, true, false),
  ('217c4f32-ed70-5bb6-81f7-9a4c205527b1', (SELECT id FROM categories WHERE slug = 'accessories'), 'sunglasses', 'Sunglasses', 'نظارات شمسية', 'Round, square and pilot frames with UV400 lenses.', 'نظارات شمسية دائرية ومربعة وبتصميم الطيّار بعدسات UV400.', 'https://images.unsplash.com/photo-1562378867-f03e114ed186?w=1200&h=1500&q=80&auto=format&fit=crop', 4, true, false)
