  ('2fd62c12-c2e7-5999-badd-42534ba076ec', (SELECT id FROM categories WHERE slug = 'shirts'), 'linen-shirt', 'Linen Shirt', 'قميص كتان', 'Cut from pure linen that softens with every wash, this long-sleeve shirt is made for warm days. A chest pocket and a slightly relaxed fit make it easy to wear open over a tee or buttoned up.', 'قميص بأكمام طويلة من الكتان الخالص الذي يزداد نعومة مع كل غسلة، مصمَّم للأيام الدافئة. جيب على الصدر وقصّة مريحة قليلًا تجعله مناسبًا مفتوحًا فوق تيشيرت أو مغلقًا بالكامل.', 1350, NULL, 'ShiftSouq', false, true, true, '100% linen
