  ('b559edf1-3588-5615-9a02-d3966e0851e9', (SELECT id FROM categories WHERE slug = 'shirts'), 'washed-denim-shirt', 'Washed Denim Shirt', 'قميص دنيم مغسول', 'A mid-weight denim shirt with a lived-in wash and two flap chest pockets. Wear it buttoned on its own or open as a light layer over a T-shirt.', 'قميص من الدنيم متوسط السماكة بغسلة تمنحه مظهرًا مألوفًا كأنه رفيقك منذ سنوات، مع جيبين بغطاء على الصدر. يُلبس مغلقًا وحده أو مفتوحًا كطبقة خفيفة فوق تيشيرت.', 1250, NULL, 'ShiftSouq', false, false, true, '100% cotton denim
