  ('002f778f-48da-5522-a105-69170d7e9da8', (SELECT id FROM categories WHERE slug = 'polos'), 'ribbed-knit-polo', 'Ribbed Knit Polo', 'قميص بولو بنسيج مضلّع', 'A knitted polo with an open collar and no buttons, in a fine ribbed cotton that drapes softly. Smart enough for dinner out, relaxed enough for a long summer day.', 'قميص بولو منسوج بياقة مفتوحة من دون أزرار، من قطن مضلّع رفيع ينسدل بخفة. أنيق بما يكفي لعشاء خارج البيت، ومريح بما يكفي ليوم صيفي طويل.', 990, 790, 'ShiftSouq', false, false, true, '100% cotton, fine-gauge knit
